<?php require __DIR__.'/bootstrap.php';require_login();$q=db()->prepare('SELECT c.*,COUNT(i.id) inquiries FROM cars c LEFT JOIN inquiries i ON i.car_id=c.id WHERE c.owner_id=? GROUP BY c.id ORDER BY c.created_at DESC');$q->execute([current_user()['id']]);$cars=$q->fetchAll();page_top('Dealer dashboard');?><section class="dashboard"><h1>Welcome, <?=e(current_user()['name'])?></h1><p><a class="button" href="add-car.php">Add a car</a> <a class="button small" href="manage-cars.php">Manage listings</a></p><h2>Your listings</h2><table class="table"><thead><tr><th>Car</th><th>Status</th><th>Inquiries</th></tr></thead><tbody><?php foreach($cars as $car):?><tr><td><?=e($car['title'])?></td><td><?=e($car['status'])?></td><td><?=$car['inquiries']?></td></tr><?php endforeach?></tbody></table></section><?php page_bottom();
